/// Logo made of several shapes with their own colors; scaled to fit the tile keeping its aspect ratio.
struct MultiLogo {
    let width: CGFloat
    let height: CGFloat
    let parts: [(String, UInt32)]
}

struct MultiLogoView: View {
    let logo: MultiLogo
    private let paths: [(Path, Color)]

    init(logo: MultiLogo) {
        self.logo = logo
        paths = logo.parts.map { d, hex in
            (SVGPath.parse(d), Color(red: Double((hex >> 16) & 0xFF) / 255, green: Double((hex >> 8) & 0xFF) / 255, blue: Double(hex & 0xFF) / 255))
        }
    }

    var body: some View {
        Canvas { ctx, size in
            let k = min(size.width / logo.width, size.height / logo.height)
            let tx = (size.width - logo.width * k) / 2, ty = (size.height - logo.height * k) / 2
            let t = CGAffineTransform(translationX: tx, y: ty).scaledBy(x: k, y: k)
            for (p, c) in paths { ctx.fill(p.applying(t), with: .color(c)) }
        }
        .aspectRatio(logo.width / logo.height, contentMode: .fit)
    }
}
